def shoot(x):
    pete_score = 0
    phil_score = 0
    for round_data in x:
        scores = round_data[0]
        multiplier = 2 if round_data[1] else 1
        pete_hits = scores['P1'].count('X')
        phil_hits = scores['P2'].count('X')
        pete_score += pete_hits * multiplier
        phil_score += phil_hits * multiplier
    if pete_score > phil_score:
        return 'Pete Wins!'
    elif phil_score > pete_score:
        return 'Phil Wins!'
    else:
        return 'Draw!'
